import 'package:flutter/material.dart';
class SplashScreen extends StatefulWidget { const SplashScreen({super.key}); @override State<SplashScreen> createState() => _SplashScreenState(); }
class _SplashScreenState extends State<SplashScreen> with SingleTickerProviderStateMixin { late final AnimationController controller; @override void initState() { super.initState(); controller = AnimationController(vsync: this, duration: const Duration(milliseconds: 700))..forward(); Future<void>.delayed(const Duration(seconds: 2), () { if (mounted) Navigator.pushReplacementNamed(context, '/onboarding'); }); } @override void dispose() { controller.dispose(); super.dispose(); } @override Widget build(BuildContext context) => Scaffold(body: Center(child: ScaleTransition(scale: CurvedAnimation(parent: controller, curve: Curves.easeOutBack), child: const Column(mainAxisSize: MainAxisSize.min, children: <Widget>[CircleAvatar(radius:48, child: Icon(Icons.school, size:52)), SizedBox(height:16), Text('المستشار التعليمي الذكي', style: TextStyle(fontSize:24, fontWeight:FontWeight.bold)), SizedBox(height:6), Text('Smart Educational Advisor')])))); }
